//127.0.0.1"]\n\ntimeout = "5s"\n\nversion = 2\n\n## Path to mib files\n## Used by the gosmi translator.\n## To add paths when translating with netsnmp, use the MIBDIRS environment variable\n##path = ["/usr/share/snmp/DCN"]\n##translator = "gosmi"\n\ncommunity = "public"\n\nagent_host_tag = "DCN"\n\nretries = 3\n\nmax_repetitions = 100\n\n##\u8fd0\u884c\u65f6\u95f4\n[[instances.field]]\noid = "1.3.6.1.2.1.1.3.0"\nname = "sys_uptime"\nconversion = "float(2)"\n\n[[instances.field]]\noid = "1.3.6.1.4.1.6339.100.1.11.10.0"\nname = "cpu_usage"\n\n[[instances.field]]\noid = "1.3.6.1.4.1.6339.100.1.11.6.0"\nname = "mem_max"\n\n[[instances.field]]\noid = "1.3.6.1.4.1.6339.100.1.11.7.0"\nname = "mem_use"\n\n#\u7aef\u53e3\u603b\u548c\n[[instances.field]]\nname = "TotalPorts"\noid = "1.3.6.1.4.1.6339.100.3.1.0"\n\n##\u8bbe\u5907\u540d\u79f0\n[[instances.field]]\noid = "1.3.6.1.2.1.1.5.0"\nname = "sys_name"\nis_tag = true\n\n##\u4ea7\u54c1\u578b\u53f7\n[[instances.field]]\nname = "sys_pm"\noid = "1.3.6.1.4.1.6339.100.25.1.1.1.0"\nis_tag = true\n\n#\u672c\u673aIP\n[[instances.field]]\nname = "LocalIP"\noid = "1.3.6.1.2.1.4.20.1.1"\nis_tag = true\n\n#\u63a5\u53e3\u8868\u4fe1\u606f\n[[instances.table]]\nname = "interface"\ninherit_tags = ["sys_name","sys_pm","LocalIP"]\n\n#\u5404\u4e2a\u7aef\u53e3\n[[instances.table.field]]\nname = "ifDescr"\noid = "1.3.6.1.2.1.2.2.1.2"\nis_tag = true\n\n[[instances.table.field]]\nname = "ifSpeed"\noid = "1.3.6.1.2.1.2.2.1.5"\nconversion = "float(6)"\n#is_tag = true\n\n[[instances.table.field]]\nname = "ifOperStatus"\noid = "1.3.6.1.2.1.2.2.1.8"\n#is_tag = true\n\n[[instances.table.field]]\nname = "ifOutOctets"\noid = "1.3.6.1.2.1.2.2.1.16"\n\n[[instances.table.field]]\nname = "ifInOctets"\noid = "1.3.6.1.2.1.2.2.1.10"\n\n#\u805a\u5408\u72b6\u6001\n#oid = "1.3.6.1.4.1.6339.100.14.2.1.4.1.1.*"\n\n#\u805a\u5408\u7aef\u53e3\n#oid = "1.3.6.1.4.1.6339.100.14.3.1.2"\n'})}),"\n",(0,l.jsx)(e.p,{children:(0,l.jsx)(e.code,{children:"conf/input.snmp/snmp.toml"})}),"\n",(0,l.jsx)(e.pre,{children:(0,l.jsx)(e.code,{className:"language-toml",children:'# Retrieves SNMP values from remote agents\n[[instances]]\n## Agent addresses to retrieve values from.\n##   format:  agents = ["<scheme://><hostname>:<port>"]\n##   scheme:  optional, either udp, udp4, udp6, tcp, tcp4, tcp6.\n##            default is udp\n##   port:    optional\n##   example: agents = ["udp://127.0.0.1:161"]\n##            agents = ["tcp://127.0.0.1:161"]\n##            agents = ["udp4://v4only-snmp-agent"]\n#agents = ["udp://127.0.0.1:161"]\nagents = [\n    #\n]\n\n## Timeout for each request.\n# timeout = "5s"\n\n## SNMP version; can be 1, 2, or 3.\n# version = 2\n\n## Unconnected UDP socket\n## When true, SNMP responses are accepted from any address not just\n## the requested address. This can be useful when gathering from\n## redundant/failover systems.\n# unconnected_udp_socket = false\n\n## Path to mib files\n## Used by the gosmi translator.\n## To add paths when translating with netsnmp, use the MIBDIRS environment variable\n# path = ["/usr/share/snmp/mibs"]\n\n## SNMP community string.\n# community = "public"\n\n## Agent host tag\n# agent_host_tag = "agent_host"\n\n## Number of retries to attempt.\n# retries = 3\n\n## The GETBULK max-repetitions parameter.\n# max_repetitions = 10\n\n## SNMPv3 authentication and encryption options.\n##\n## Security Name.\n# sec_name = "myuser"\n## Authentication protocol; one of "MD5", "SHA", "SHA224", "SHA256", "SHA384", "SHA512" or "".\n# auth_protocol = "MD5"\n## Authentication password.\n# auth_password = "pass"\n## Security Level; one of "noAuthNoPriv", "authNoPriv", or "authPriv".\n# sec_level = "authNoPriv"\n## Context Name.\n# context_name = ""\n## Privacy protocol used for encrypted messages; one of "DES", "AES", "AES192", "AES192C", "AES256", "AES256C", or "".\n### Protocols "AES192", "AES192", "AES256", and "AES256C" require the underlying net-snmp tools\n### to be compiled with --enable-blumenthal-aes (htt